<p>Enable the legacy handling of JSON field name conflicts.  This lowercases
and strips underscored from the fields before comparison in proto3 only.
The new behavior takes <code>json_name</code> into account and applies to proto2 as
well.</p>
<p>This should only be used as a temporary measure against broken builds due
to the change in behavior for JSON field name conflicts.</p>
<p>TODO This is legacy behavior we plan to remove once downstream
teams have had time to migrate.</p>
