        val to_string : t -> string
        val from_string_exn : string -> t

        (**/**)
      end

      and VisibilityFeature : sig
        module rec DefaultSymbolVisibility : sig
          type t =
            | DEFAULT_SYMBOL_VISIBILITY_UNKNOWN
            | EXPORT_ALL
                (** {%html:
<p>Default pre-EDITION_2024, all UNSET visibility are export.</p>
%}
                *)
            | EXPORT_TOP_LEVEL
                (** {%html:
<p>All top-level symbols default to export, nested default to local.</p>
%}
                *)
            | LOCAL_ALL  (** {%html:
<p>All symbols default to local.</p>
%} *)
            | STRICT
                (** {%html:
<p>All symbols local by default. Nested types cannot be exported.
With special case caveat for message { enum {} reserved 1 to max; }
This is the recommended setting for new protos.</p>
%}
                *)

          val name : unit -> string
          (** Fully qualified protobuf name of this enum *)

          (**/**)

          val to_int : t -> int
          val from_int : int -> t Runtime'.Result.t
          val from_int_exn : int -> t
          val to_string : t -> string
          val from_string_exn : string -> t

          (**/**)
        end

        type t = unit

        val make : unit -> t
        (** Helper function to generate a message using default values *)

        val to_proto : t -> Runtime'.Writer.t
        (** Serialize the message to binary format *)

        val from_proto :
          Runtime'.Reader.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from binary format *)

        val to_json : Runtime'.Json_options.t -> t -> Runtime'.Json.t
        (** Serialize to Json (compatible with Yojson.Basic.t) *)

        val from_json :
          Runtime'.Json.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from Json (compatible with Yojson.Basic.t) *)

        val name : unit -> string
        (** Fully qualified protobuf name of this message *)

        (**/**)

        type make_t = unit -> t

        val merge : t -> t -> t
        val to_proto' : Runtime'.Writer.t -> t -> unit
        val from_proto_exn : Runtime'.Reader.t -> t
        val from_json_exn : Runtime'.Json.t -> t

        (**/**)
      end

      and ProtoLimitsFeature : sig
        module rec EnforceProtoLimits : sig
          type t =
            | PROTO_LIMITS_UNKNOWN
            | LEGACY_NO_EXPLICIT_LIMITS
                (** {%html:
<p>Default pre-EDITION_2026: there are no limit enforcement at the protoc
level. Practical limits still exist, but they will tend to fail while
compiling protoc-generated code, and these limits tend to be language
or toolchain specific.</p>
%}
                *)
            | PROTO_LIMITS2026
                (** {%html:
<p>A set of limits enforced by Edition 2026 by default. For a detailed
list of all the limits please consult the Edition 2026 documentation.</p>
%}
                *)

          val name : unit -> string
          (** Fully qualified protobuf name of this enum *)

          (**/**)

          val to_int : t -> int
          val from_int : int -> t Runtime'.Result.t
          val from_int_exn : int -> t
          val to_string : t -> string
          val from_string_exn : string -> t

          (**/**)
        end

        type t = unit

        val make : unit -> t
        (** Helper function to generate a message using default values *)

        val to_proto : t -> Runtime'.Writer.t
        (** Serialize the message to binary format *)

        val from_proto :
          Runtime'.Reader.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from binary format *)

        val to_json : Runtime'.Json_options.t -> t -> Runtime'.Json.t
        (** Serialize to Json (compatible with Yojson.Basic.t) *)

        val from_json :
          Runtime'.Json.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from Json (compatible with Yojson.Basic.t) *)

        val name : unit -> string
        (** Fully qualified protobuf name of this message *)

        (**/**)

        type make_t = unit -> t

        val merge : t -> t -> t
        val to_proto' : Runtime'.Writer.t -> t -> unit
        val from_proto_exn : Runtime'.Reader.t -> t
        val from_json_exn : Runtime'.Json.t -> t

        (**/**)
      end

      type t = {
        field_presence : FieldPresence.t option;
        enum_type : EnumType.t option;
        repeated_field_encoding : RepeatedFieldEncoding.t option;
        utf8_validation : Utf8Validation.t option;
        message_encoding : MessageEncoding.t option;
        json_format : JsonFormat.t option;
            (** {%html:
<p>for https://github.com/bufbuild/protobuf-es</p>
%} *)
        enforce_naming_style : EnforceNamingStyle.t option;
        default_symbol_visibility :
          VisibilityFeature.DefaultSymbolVisibility.t option;
        enforce_proto_limits : ProtoLimitsFeature.EnforceProtoLimits.t option;
        extensions' : Runtime'.Extensions.t;
      }

      val make :
        ?field_presence:FieldPresence.t ->
        ?enum_type:EnumType.t ->
        ?repeated_field_encoding:RepeatedFieldEncoding.t ->
        ?utf8_validation:Utf8Validation.t ->
        ?message_encoding:MessageEncoding.t ->
        ?json_format:JsonFormat.t ->
        ?enforce_naming_style:EnforceNamingStyle.t ->
        ?default_symbol_visibility:VisibilityFeature.DefaultSymbolVisibility.t ->
        ?enforce_proto_limits:ProtoLimitsFeature.EnforceProtoLimits.t ->
        ?extensions':Runtime'.Extensions.t ->
        unit ->
        t
      (** Helper function to generate a message using default values *)

      val to_proto : t -> Runtime'.Writer.t
      (** Serialize the message to binary format *)

      val from_proto :
        Runtime'.Reader.t -> (t, [> Runtime'.Result.error ]) result
      (** Deserialize from binary format *)

      val to_json : Runtime'.Json_options.t -> t -> Runtime'.Json.t
      (** Serialize to Json (compatible with Yojson.Basic.t) *)

      val from_json : Runtime'.Json.t -> (t, [> Runtime'.Result.error ]) result
      (** Deserialize from Json (compatible with Yojson.Basic.t) *)

      val name : unit -> string
      (** Fully qualified protobuf name of this message *)

      (**/**)

      type make_t =
        ?field_presence:FieldPresence.t ->
        ?enum_type:EnumType.t ->
        ?repeated_field_encoding:RepeatedFieldEncoding.t ->
        ?utf8_validation:Utf8Validation.t ->
        ?message_encoding:MessageEncoding.t ->
        ?json_format:JsonFormat.t ->
        ?enforce_naming_style:EnforceNamingStyle.t ->
        ?default_symbol_visibility:VisibilityFeature.DefaultSymbolVisibility.t ->
        ?enforce_proto_limits:ProtoLimitsFeature.EnforceProtoLimits.t ->
        ?extensions':Runtime'.Extensions.t ->
        unit ->
        t

      val merge : t -> t -> t
      val to_proto' : Runtime'.Writer.t -> t -> unit
      val from_proto_exn : Runtime'.Reader.t -> t
      val from_json_exn : Runtime'.Json.t -> t

      (**/**)
    end

    (** {%html:
<p>A compiled specification for the defaults of a set of features.  These
messages are generated from FeatureSet extensions and can be used to seed
feature resolution. The resolution with this object becomes a simple search
for the closest matching edition, followed by proto merges.</p>
%}
    *)
    and FeatureSetDefaults : sig
      (** {%html:
<p>A map from every known edition with a unique set of defaults to its
defaults. Not all editions may be contained here.  For a given edition,
the defaults at the closest matching edition ordered at or before it should
be used.  This field must be in strict ascending order by edition.</p>
%}
      *)
      module rec FeatureSetEditionDefault : sig
        type t = {
          edition : Edition.t option;
          overridable_features : FeatureSet.t option;
              (** {%html:
<p>Defaults of features that can be overridden in this edition.</p>
%}
              *)
          fixed_features : FeatureSet.t option;
              (** {%html:
<p>Defaults of features that can't be overridden in this edition.</p>
%}
              *)
        }

        val make :
          ?edition:Edition.t ->
          ?overridable_features:FeatureSet.t ->
          ?fixed_features:FeatureSet.t ->
          unit ->
          t
        (** Helper function to generate a message using default values *)

        val to_proto : t -> Runtime'.Writer.t
        (** Serialize the message to binary format *)

        val from_proto :
          Runtime'.Reader.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from binary format *)

        val to_json : Runtime'.Json_options.t -> t -> Runtime'.Json.t
        (** Serialize to Json (compatible with Yojson.Basic.t) *)

        val from_json :
          Runtime'.Json.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from Json (compatible with Yojson.Basic.t) *)

        val name : unit -> string
        (** Fully qualified protobuf name of this message *)

        (**/**)

        type make_t =
          ?edition:Edition.t ->
          ?overridable_features:FeatureSet.t ->
          ?fixed_features:FeatureSet.t ->
          unit ->
          t

        val merge : t -> t -> t
        val to_proto' : Runtime'.Writer.t -> t -> unit
        val from_proto_exn : Runtime'.Reader.t -> t
        val from_json_exn : Runtime'.Json.t -> t

        (**/**)
      end

      type t = {
        defaults : FeatureSetEditionDefault.t list;
        minimum_edition : Edition.t option;
            (** {%html:
<p>The minimum supported edition (inclusive) when this was constructed.
Editions before this will not have defaults.</p>
%}
            *)
        maximum_edition : Edition.t option;
            (** {%html:
<p>The maximum known edition (inclusive) when this was constructed. Editions
after this will not have reliable defaults.</p>
%}
            *)
      }

      val make :
        ?defaults:FeatureSetEditionDefault.t list ->
        ?minimum_edition:Edition.t ->
        ?maximum_edition:Edition.t ->
        unit ->
        t
      (** Helper function to generate a message using default values *)

      val to_proto : t -> Runtime'.Writer.t
      (** Serialize the message to binary format *)

      val from_proto :
        Runtime'.Reader.t -> (t, [> Runtime'.Result.error ]) result
      (** Deserialize from binary format *)

      val to_json : Runtime'.Json_options.t -> t -> Runtime'.Json.t
      (** Serialize to Json (compatible with Yojson.Basic.t) *)

      val from_json : Runtime'.Json.t -> (t, [> Runtime'.Result.error ]) result
      (** Deserialize from Json (compatible with Yojson.Basic.t) *)

      val name : unit -> string
      (** Fully qualified protobuf name of this message *)

      (**/**)

      type make_t =
        ?defaults:FeatureSetEditionDefault.t list ->
        ?minimum_edition:Edition.t ->
        ?maximum_edition:Edition.t ->
        unit ->
        t

      val merge : t -> t -> t
      val to_proto' : Runtime'.Writer.t -> t -> unit
      val from_proto_exn : Runtime'.Reader.t -> t
      val from_json_exn : Runtime'.Json.t -> t

      (**/**)
    end

    (** {%html:
<p>Encapsulates information about the original source file from which a
FileDescriptorProto was generated.</p>
<p>===================================================================
Optional source code info</p>
%}
    *)
    and SourceCodeInfo : sig
      module rec Location : sig
        type t = {
          path : int list;
              (** {%html:
<p>Identifies which part of the FileDescriptorProto was defined at this
location.</p>
<p>Each element is a field number or an index.  They form a path from
the root FileDescriptorProto to the place where the definition appears.
For example, this path:</p>
<pre><code> [ 4, 3, 2, 7, 1 ]
</code></pre>
<p>refers to:</p>
<pre><code> file.message_type(3)  // 4, 3
     .field(7)         // 2, 7
     .name()           // 1
</code></pre>
<p>This is because FileDescriptorProto.message_type has field number 4:</p>
<pre><code> repeated DescriptorProto message_type = 4;
</code></pre>
<p>and DescriptorProto.field has field number 2:</p>
<pre><code> repeated FieldDescriptorProto field = 2;
</code></pre>
<p>and FieldDescriptorProto.name has field number 1:</p>
<pre><code> optional string name = 1;
</code></pre>
<p>Thus, the above path gives the location of a field name.  If we removed
the last element:</p>
<pre><code> [ 4, 3, 2, 7 ]
</code></pre>
<p>this path refers to the whole field declaration (from the beginning
of the label to the terminating semicolon).</p>
<p>For options, the path refers to the interpreted option in the descriptor.
E.g., for a custom option <code>(my_opt) = &quot;foo&quot;</code> on a message using extension
number 10101, the path is:</p>
<pre><code> [ 4, 3, 7, 10101 ]
</code></pre>
<p>refers to:</p>
<pre><code> file.message_type(3)     // 4, 3
     .options()           // 7
     .my_opt()            // 10101
</code></pre>
<p>Sub-locations corresponding to the interpreted option's corresponding
<code>UninterpretedOption</code> are also appended to the interpreted option, which
deviates from the actual FileDescriptorProto path. E.g.:</p>
<pre><code> [ 4, 3, 7, 10101, 2 ]
</code></pre>
<p>refers to the option name <code>(my_opt)</code>, and:</p>
<pre><code> [ 4, 3, 7, 10101, 7 ]
</code></pre>
<p>refers to the &quot;foo&quot; string value of the option.</p>
%}
              *)
          span : int list;
              (** {%html:
<p>Always has exactly three or four elements: start line, start column,
end line (optional, otherwise assumed same as start line), end column.
These are packed into a single field for efficiency.  Note that line
and column numbers are zero-based -- typically you will want to add
1 to each before displaying to a user.</p>
%}
              *)
          leading_comments : string option;
              (** {%html:
<p>If this SourceCodeInfo represents a complete declaration, these are any
comments appearing before and after the declaration which appear to be
attached to the declaration.</p>
<p>A series of line comments appearing on consecutive lines, with no other
tokens appearing on those lines, will be treated as a single comment.</p>
<p>leading_detached_comments will keep paragraphs of comments that appear
before (but not connected to) the current element. Each paragraph,
separated by empty lines, will be one comment element in the repeated
field.</p>
<p>Only the comment content is provided; comment markers (e.g. //) are
stripped out.  For block comments, leading whitespace and an asterisk
will be stripped from the beginning of each line other than the first.
Newlines are included in the output.</p>
<p>Examples:</p>
<pre><code> optional int32 foo = 1;  // Comment attached to foo.
</code></pre>
<p>Comment attached to bar.</p>
<pre><code> optional int32 bar = 2;

 optional string baz = 3;
</code></pre>
<p>Comment attached to baz.
Another line attached to baz.</p>
<p>Comment attached to moo.</p>
<p>Another line attached to moo.</p>
<pre><code> optional double moo = 4;
</code></pre>
<p>Detached comment for corge. This is not leading or trailing comments
to moo or corge because there are blank lines separating it from
both.</p>
<p>Detached comment for corge paragraph 2.</p>
<pre><code> optional string corge = 5;
 /* Block comment attached
  * to corge.  Leading asterisks
  * will be removed. */
 /* Block comment attached to
  * grault. */
 optional int32 grault = 6;
</code></pre>
<p>ignored detached comments.</p>
%}
              *)
          trailing_comments : string option;
          leading_detached_comments : string list;
        }

        val make :
          ?path:int list ->
          ?span:int list ->
          ?leading_comments:string ->
          ?trailing_comments:string ->
          ?leading_detached_comments:string list ->
          unit ->
          t
        (** Helper function to generate a message using default values *)

        val to_proto : t -> Runtime'.Writer.t
        (** Serialize the message to binary format *)

        val from_proto :
          Runtime'.Reader.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from binary format *)

        val to_json : Runtime'.Json_options.t -> t -> Runtime'.Json.t
        (** Serialize to Json (compatible with Yojson.Basic.t) *)

        val from_json :
          Runtime'.Json.t -> (t, [> Runtime'.Result.error ]) result
        (** Deserialize from Json (compatible with Yojson.Basic.t) *)

        val name : unit -> string
        (** Fully qualified protobuf name of this message *)

        (**/**)

        type make_t =
          ?path:int list ->
          ?span:int list ->
          ?leading_comments:string ->
          ?trailing_comments:string ->
          ?leading_detached_comments:string list ->
          unit ->
          t

        val merge : t -> t -> t
        val to_proto' : Runtime'.Writer.t -> t -> unit
        val from_proto_exn : Runtime'.Reader.t -> t
        val from_json_exn : Runtime'.Json.t -> t

        (**/**)
      end

      type t = {
        location : Location.t list;
            (** {%html:
<p>A Location identifies a piece of source code in a .proto file which
corresponds to a particular definition.  This information is intended
to be useful to IDEs, code indexers, documentation generators, and similar
tools.</p>
<p>For example, say we have a file like:</p>
<pre><code> message Foo {
   optional string foo = 1;
 }
</code></pre>
<p>Let's look at just the field definition:</p>
<pre><code> optional string foo = 1;
 ^       ^^     ^^  ^  ^^^
 a       bc     de  f  ghi
</code></pre>
<p>We have the following locations:</p>
<pre><code> span   path               represents
 [a,i)  [ 4, 0, 2, 0 ]     The whole field definition.
 [a,b)  [ 4, 0, 2, 0, 4 ]  The label (optional).
 [c,d)  [ 4, 0, 2, 0, 5 ]  The type (string).
 [e,f)  [ 4, 0, 2, 0, 1 ]  The name (foo).
 [g,h)  [ 4, 0, 2, 0, 3 ]  The number (1).
</code></pre>
<p>Notes:</p>
<ul>
<li>A location may refer to a repeated field itself (i.e. not to any
particular index within it).  This is used whenever a set of elements are
logically enclosed in a single code segment.  For example, an entire
extend block (possibly containing multiple extension definitions) will
have an outer location whose path refers to the &quot;extensions&quot; repeated
field without an index.
</li>
<li>Multiple locations may have the same path.  This happens when a single
logical declaration is spread out across multiple places.  The most
obvious example is the &quot;extend&quot; block again -- there may be multiple
extend blocks in the same scope, each of which will have the same path.
</li>
<li>A location's span is not always a subset of its parent's span.  For
example, the &quot;extendee&quot; of an extension declaration appears at the
beginning of the &quot;extend&quot; block and is shared by all extensions within
the block.
</li>
<li>Just because a location's span is a subset of some other location's span
does not mean that it is a descendant.  For example, a &quot;group&quot; defines
both a type and a field in a single declaration.  Thus, the locations
corresponding to the type and field and their components will overlap.
</li>
<li>Code which tries to interpret locations should probably be designed to
ignore those that it doesn't understand, as more types of locations could
be recorded in the future.
</li>
</ul>
