        unverified_lazy : bool;
            (** {%html:
<p>unverified_lazy does no correctness checks on the byte stream. This should
only be used where lazy with verification is prohibitive for performance
reasons.</p>
%}
            *)
        debug_redact : bool;
            (** {%html:
<p>Indicate that the field value should not be printed out when using debug
formats, e.g. when the field contains sensitive credentials.</p>
%}
            *)
        retention : OptionRetention.t option;
        targets : OptionTargetType.t list;
            (** {%html:
<p>reserve target, target_obsolete_do_not_use</p>
