        feature_support : FeatureSupport.t option;
        uninterpreted_option : UninterpretedOption.t list;
            (** {%html:
<p>The parser stores options it doesn't recognize here. See above.</p>
%}
            *)
        extensions' : Runtime'.Extensions.t;
      }

