extension (denoted with parentheses in options specs in .proto files).
E.g.,{ [&quot;foo&quot;, false], [&quot;bar.baz&quot;, true], [&quot;moo&quot;, false] } represents
&quot;foo.(bar.baz).moo&quot;.</p>
%}
